import { test, expect } from 'bun:test';
import { last, unique } from '../src/list.js';
test('last', () => expect(last([1, 2])).toBe(2));
test('unique keeps first occurrences in order', () => expect(unique([3, 1, 3, 2, 1])).toEqual([3, 1, 2]));
test('unique of empty', () => expect(unique([])).toEqual([]));

