import { test, expect } from 'bun:test';
import { unique } from '../src/list.js';
test('does not mutate and keeps 1 and "1" apart', () => {
  const xs = [1, '1', 1];
  expect(unique(xs)).toEqual([1, '1']);
  expect(xs).toEqual([1, '1', 1]);
});
